public class TenantGate implements Filter {
  @Override public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
      throws IOException, ServletException {
    Identity id = authenticate(req);              // this gate's own evidence
    if (!policy.allows(id, req)) {                // fail closed
      ((HttpServletResponse) res).sendError(403);
      return;                                     // short-circuit: inner gates never run
    }
    chain.doFilter(req, res);                     // delegate to the next gate
  }
}

