Service inner = rawService;
for (Rule rule : List.of(tenantRule, edgeRule)) {   // gates nest outward
    Service next = inner;
    inner = (Service) Proxy.newProxyInstance(
        Service.class.getClassLoader(), new Class<?>[] {Service.class},
        (proxy, method, args) -> {
          Identity id = verify(method, args);        // own evidence
          if (!rule.allows(id, method, args)) throw new AccessDeniedException(method.getName());
          return method.invoke(next, args);          // delegate inward
        });
}
